{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a broken map of the ruined city.",
      "visual_description": "Mara stands at a cracked stone table, unrolling a tattered map under flickering torchlight.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The oracle lamp hovers near Mara, its flame eye flickering as it speaks in a low voice.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver descends through a shattered window.",
      "visual_description": "Glass diver slips through a broken stained-glass window, landing silently on rubble in a ruined hall.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through a narrow alley.",
      "visual_description": "Tin fox darts between collapsed pillars, its blue eyes scanning for danger in the shadows.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector snores near the castle gates.",
      "visual_description": "Sleeping tax collector slumps against the rusted iron gates, a ledger under his head, stamped papers scattered.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and the glass diver meet at the fountain square.",
      "visual_description": "Mara consults her compass as glass diver approaches across a cracked marble fountain, water trickling.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp illuminates a hidden passage beneath the old armory.",
      "visual_description": "Oracle lamp glows brightly, revealing a stone staircase hidden behind fallen shelves in a dusty armory.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox triggers a trap, alerting armored patrols.",
      "visual_description": "Tin fox steps on a pressure plate; a crossbow bolt whizzes past as metal footsteps echo nearby.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver hides in a cracked mirror to avoid detection.",
      "visual_description": "Glass diver presses into a large standing mirror, his body rippling like water as armored figures march past.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara confronts the sleeping tax collector for a key.",
      "visual_description": "Mara shakes the sleeping tax collector awake; he mutters and points at a key hanging from a chain on his belt.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp warns of a magical door that reads minds.",
      "visual_description": "In a narrow corridor, the oracle lamp's flame dims as it whispers warning about an ornate golden door covered in runes.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver swims through the magical door's mirror surface.",
      "visual_description": "Glass diver touches the golden door; his hand sinks into it like liquid glass, then he steps through entirely.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox carries a small key back from the tower.",
      "visual_description": "Tin fox trots out of a spiral staircase, a brass key clamped in its metal jaws, gears whirring.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Mara reads a faded banner to find the escape route.",
      "visual_description": "Mara brushes dust off a frayed royal banner, revealing a hidden map marking an underground exit.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector finally wakes and stumbles along.",
      "visual_description": "Sleeping tax collector shuffles after the group, rubbing his eyes and clutching his ledger.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols block the main bridge.",
      "visual_description": "At the bridge entrance, torch-wielding armored figures stand in formation, their metal boots clanking.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver creates a distraction by shattering a stained-glass window.",
      "visual_description": "Glass diver leaps up and crashes through a high window, sending shards of colored glass raining down to draw the patrols away.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes across the bridge as dawn breaks.",
      "visual_description": "Mara, glass diver, tin fox, oracle lamp, and the tax collector run across the stone bridge, the ruined city silhouetted behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ],
  "gate_token": "dKQnhgjU_AJXREb6HixVEA"
}

